def check(inp, actual, expected):
    if expected == "":
        return actual == ""
    if not isinstance(actual, str):
        return False
    letters = set("".join(inp["words"]))
    if len(actual) != len(letters) or set(actual) != letters:
        return False
    pos = {ch: i for i, ch in enumerate(actual)}
    words = inp["words"]
    for a, b in zip(words, words[1:]):
        for x, y in zip(a, b):
            if x != y:
                if pos[x] > pos[y]:
                    return False
                break
    return True
